const moveConversationLinks = `-- name: MoveConversationLinks :exec
DELETE FROM conversation_links
WHERE organization_id = $1 AND (from_id = $2 OR to_id = $2)
`

type MoveConversationLinksParams struct {
	OrganizationID int64 `json:"organization_id"`
	ID             int64 `json:"id"`
}

// Links of a merged conversation are dropped: the target keeps its own and
// the source stays reachable through merged_into_id.
func (q *Queries) MoveConversationLinks(ctx context.Context, arg MoveConversationLinksParams) error {
	_, err := q.db.Exec(ctx, moveConversationLinks, arg.OrganizationID, arg.ID)
	return err
}

const moveConversationMessages = `-- name: MoveConversationMessages :execrows

UPDATE messages SET conversation_id = $1
WHERE organization_id = $2 AND conversation_id = $3
`

type MoveConversationMessagesParams struct {
	IntoID         int64 `json:"into_id"`
	OrganizationID int64 `json:"organization_id"`
	FromID         int64 `json:"from_id"`
}

// CF-98: merge / split, linked conversations and side conversations.
// Moves every message of one conversation into another (merge).
func (q *Queries) MoveConversationMessages(ctx context.Context, arg MoveConversationMessagesParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveConversationMessages, arg.IntoID, arg.OrganizationID, arg.FromID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const moveMessagesFrom = `-- name: MoveMessagesFrom :execrows
UPDATE messages SET conversation_id = $1
WHERE organization_id = $2 AND conversation_id = $3
  AND (id = $4 OR ($5::boolean AND id > $4))
`

type MoveMessagesFromParams struct {
	IntoID         int64 `json:"into_id"`
	OrganizationID int64 `json:"organization_id"`
	FromID         int64 `json:"from_id"`
	FirstID        int64 `json:"first_id"`
	Following      bool  `json:"following"`
}

// Moves the messages of a conversation from first_id on (or only first_id)
// into another conversation (split).
func (q *Queries) MoveMessagesFrom(ctx context.Context, arg MoveMessagesFromParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveMessagesFrom,
		arg.IntoID,
		arg.OrganizationID,
		arg.FromID,
		arg.FirstID,
		arg.Following,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

